# ==============================================================================
# Adaptive Rejection Sampling (ARS) - Gilks & Wild (1992)
# Reference:
#   Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for Gibbs
#   sampling. Journal of the Royal Statistical Society: Series C (Applied
#   Statistics), 41(2), 337-348.
# ==============================================================================

# ------------------------------------------------------------------------------
# Module 1: Numerical Utilities (Log-Space Stabilization)
# ------------------------------------------------------------------------------

#' Numerically stable computation of log(exp(a) + exp(b))
#' Avoids overflow/underflow across arbitrary log-density scales.
log_add_exp <- function(a, b) {
  m <- pmax(a, b)
  both_neg_inf <- (a == -Inf) & (b == -Inf)
  res <- m + log1p(exp(-abs(a - b)))
  res[both_neg_inf] <- -Inf
  res
}

#' Numerically stable log-sum-exp over a numeric vector
log_sum_exp <- function(v) {
  finite_v <- v[is.finite(v)]
  if (length(finite_v) == 0L) {
    return(-Inf)
  }
  m <- max(finite_v)
  m + log(sum(exp(v - m)))
}


# ------------------------------------------------------------------------------
# Module 2: Input Validation & Target Distribution S3 Class ("ars_target")
# ------------------------------------------------------------------------------

#' Resolve and validate the user-supplied density function or expression
resolve_density_callable <- function(f, extra_args, eval_env) {
  if (missing(f) || is.null(f)) {
    stop("Invalid input 'f': primary density input must be provided.")
  }

  if ("log" %in% names(extra_args) && isTRUE(extra_args[["log"]])) {
    stop("Invalid argument 'log = TRUE': 'f' must return the (unnormalized) density, not log-density.")
  }

  has_log_arg <- FALSE

  if (is.character(f)) {
    if (length(f) != 1L || is.na(f) || !nzchar(f)) {
      stop("Invalid input 'f': character input must be a single non-empty function name.")
    }
    if (!exists(f, mode = "function", envir = eval_env, inherits = TRUE)) {
      stop(sprintf("Invalid input 'f': function '%s' not found.", f))
    }
    fn <- get(f, mode = "function", envir = eval_env, inherits = TRUE)
  } else if (is.function(f)) {
    fn <- f
  } else if (is.expression(f) || is.call(f)) {
    if (is.expression(f) && length(f) == 0L) {
      stop("Invalid input 'f': expression cannot be empty.")
    }
    if (length(extra_args) > 0L) {
      stop("Extra '...' arguments are only supported when 'f' is a function, not an expression.")
    }
    expr_obj <- if (is.expression(f)) f[[1L]] else f
    vars <- all.vars(expr_obj)
    var_name <- if ("x" %in% vars || length(vars) == 0L) "x" else if (length(vars) == 1L) vars[1L] else "x"

    call_f <- function(x) {
      env_list <- list(x = x)
      if (var_name != "x") {
        env_list[[var_name]] <- x
      }
      eval(expr_obj, envir = env_list, enclos = eval_env)
    }
    return(list(call_f = call_f, call_f_log = NULL, has_log_arg = FALSE))
  } else {
    stop("Invalid input 'f': must be a vectorized function, R expression, or function name.")
  }

  fn_formals <- formals(fn)
  if (!is.null(fn_formals) && ("log" %in% names(fn_formals)) && !("log" %in% names(extra_args))) {
    has_log_arg <- TRUE
  }

  call_f <- function(x) {
    do.call(fn, c(list(x), extra_args))
  }

  call_f_log <- if (has_log_arg) {
    function(x) {
      do.call(fn, c(list(x), extra_args, list(log = TRUE)))
    }
  } else {
    NULL
  }

  list(call_f = call_f, call_f_log = call_f_log, has_log_arg = has_log_arg)
}

#' Validate all user inputs and construct an "ars_target" S3 object
validate_ars_inputs <- function(f,
                                n,
                                domain = c(-Inf, Inf),
                                x_init = NULL,
                                lower = NULL,
                                upper = NULL,
                                bounds = NULL,
                                max_points = 100L,
                                eps = 1e-6,
                                extra_args = list(),
                                eval_env = parent.frame()) {
  # 1. Validate sample count n
  if (missing(n) || is.null(n) || !is.numeric(n) || length(n) != 1L ||
      is.na(n) || !is.finite(n) || n < 1 || abs(n - round(n)) > 1e-12) {
    stop("Invalid sample count 'n': must be a single positive integer (>= 1).")
  }
  n <- as.integer(round(n))

  # 2. Resolve and validate domain / bounds / lower / upper
  if (!is.null(bounds)) {
    if (!is.numeric(bounds) || length(bounds) != 2L || any(is.na(bounds))) {
      stop("Invalid 'bounds': must be a numeric vector of length 2 without NA/NaN.")
    }
    domain <- bounds
  }
  if (!is.numeric(domain) || length(domain) != 2L || any(is.na(domain))) {
    stop("Invalid 'domain': must be a numeric vector of length 2 without NA/NaN.")
  }
  if (!is.null(lower)) {
    if (!is.numeric(lower) || length(lower) != 1L || is.na(lower)) {
      stop("Invalid 'lower': must be a single numeric value without NA/NaN.")
    }
    domain[1L] <- lower
  }
  if (!is.null(upper)) {
    if (!is.numeric(upper) || length(upper) != 1L || is.na(upper)) {
      stop("Invalid 'upper': must be a single numeric value without NA/NaN.")
    }
    domain[2L] <- upper
  }
  if (domain[1L] >= domain[2L]) {
    stop(sprintf(
      "Invalid 'domain' [%s, %s]: lower bound must be strictly less than upper bound.",
      format(domain[1L]), format(domain[2L])
    ))
  }

  # 3. Validate tuning parameters max_points and eps
  if (!is.numeric(max_points) || length(max_points) != 1L || is.na(max_points) ||
      !is.finite(max_points) || max_points < 5 || abs(max_points - round(max_points)) > 1e-12) {
    stop("Invalid 'max_points': must be an integer >= 5.")
  }
  max_points <- as.integer(round(max_points))

  if (!is.numeric(eps) || length(eps) != 1L || is.na(eps) || !is.finite(eps) || eps <= 0 || eps >= 0.1) {
    stop("Invalid 'eps': must be a finite positive scalar in (0, 0.1).")
  }

  # 4. Validate optional initial abscissae x_init
  if (!is.null(x_init)) {
    if (!is.numeric(x_init) || length(x_init) < 1L || any(is.na(x_init)) || any(!is.finite(x_init))) {
      stop("Invalid 'x_init': must be a finite numeric vector without NA/NaN.")
    }
    if (any(x_init < domain[1L] | x_init > domain[2L])) {
      stop("Invalid 'x_init': all initial points must lie within 'domain'.")
    }
    x_init <- sort(unique(as.numeric(x_init)))
  }

  # 5. Resolve density callable and verify vectorization on test points in domain
  resolved <- resolve_density_callable(f, extra_args = extra_args, eval_env = eval_env)

  test_pts <- select_probe_points(domain)
  probe_val <- tryCatch(
    suppressWarnings(resolved$call_f(test_pts)),
    error = function(e) {
      stop(sprintf("Invalid density input 'f': failed to evaluate on numeric vector (%s).", conditionMessage(e)))
    }
  )
  if (!is.numeric(probe_val) || length(probe_val) != length(test_pts)) {
    stop("Invalid density input 'f': must be vectorized and return a numeric vector matching the length of 'x'.")
  }
  if (any(is.nan(probe_val))) {
    stop("Invalid density input 'f': density returned NaN inside domain (check distribution parameters).")
  }
  if (any(probe_val < 0, na.rm = TRUE)) {
    stop("Invalid density input 'f': density evaluated to negative value(s).")
  }

  target <- structure(
    list(
      call_f = resolved$call_f,
      call_f_log = resolved$call_f_log,
      has_log_arg = resolved$has_log_arg,
      domain = as.numeric(domain),
      eps = as.numeric(eps),
      max_points = max_points
    ),
    class = "ars_target"
  )

  list(target = target, n = n, x_init = x_init)
}

#' Choose three interior test points in domain to verify vectorized evaluation
select_probe_points <- function(domain) {
  L <- domain[1L]
  U <- domain[2L]
  if (is.finite(L) && is.finite(U)) {
    L + (U - L) * c(0.25, 0.50, 0.75)
  } else if (is.finite(L)) {
    L + c(0.25, 1.0, 2.5)
  } else if (is.finite(U)) {
    U - c(2.5, 1.0, 0.25)
  } else {
    c(-1.0, 0.0, 1.0)
  }
}

#' S3 print method for ars_target
print.ars_target <- function(x, ...) {
  cat(sprintf(
    "<ars_target> domain = [%s, %s], log_support = %s, eps = %.2e\n",
    format(x$domain[1L]), format(x$domain[2L]),
    as.character(x$has_log_arg), x$eps
  ))
  invisible(x)
}

#' Evaluate h(x) = log f(x) safely with negativity and NaN checks
eval_log_density <- function(target, x) {
  if (length(x) == 0L) {
    return(numeric(0L))
  }

  out_of_bounds <- (x < target$domain[1L]) | (x > target$domain[2L])
  hx <- rep(-Inf, length(x))
  in_idx <- which(!out_of_bounds)
  if (length(in_idx) == 0L) {
    return(hx)
  }

  x_in <- x[in_idx]
  fx <- suppressWarnings(target$call_f(x_in))
  if (!is.numeric(fx) || length(fx) != length(x_in)) {
    stop("Invalid density evaluation: 'f' failed to return a numeric vector of matching length.")
  }
  if (any(is.nan(fx))) {
    stop("Invalid density evaluation: density returned NaN inside domain.")
  }
  if (any(fx < 0, na.rm = TRUE)) {
    stop("Invalid density function: density evaluated to negative value(s).")
  }

  hx_in <- suppressWarnings(log(fx))

  # Distinguish floating-point underflow (fx == 0 but log f > -Inf) from true zero density
  if (target$has_log_arg && any(fx == 0)) {
    zero_local <- which(fx == 0)
    hx_exact <- tryCatch(
      suppressWarnings(target$call_f_log(x_in[zero_local])),
      error = function(e) rep(-Inf, length(zero_local))
    )
    if (is.numeric(hx_exact) && length(hx_exact) == length(zero_local) && !any(is.nan(hx_exact))) {
      hx_in[zero_local] <- hx_exact
    }
  }

  hx[in_idx] <- hx_in
  hx
}

#' Compute h(x) and numerical derivative h'(x) with boundary awareness
#' Also performs local second-difference concavity verification.
compute_log_density_and_deriv <- function(target, x, h_vals = NULL) {
  m <- length(x)
  if (m == 0L) {
    return(list(h = numeric(0L), h_prime = numeric(0L)))
  }

  L <- target$domain[1L]
  U <- target$domain[2L]

  if (is.null(h_vals)) {
    h_vals <- eval_log_density(target, x)
  }
  if (any(!is.finite(h_vals))) {
    stop("Cannot compute derivative of log-density at point(s) where density is zero or infinite.")
  }

  h_prime <- numeric(m)
  delta <- target$eps * pmax(1.0, abs(x))

  if (is.finite(L) && is.finite(U)) {
    delta <- pmin(delta, 0.1 * (U - L))
  }

  at_left <- is.finite(L) & (x <= L + 1e-15 * pmax(1.0, abs(L)))
  at_right <- is.finite(U) & (x >= U - 1e-15 * pmax(1.0, abs(U)))
  interior <- !(at_left | at_right)

  # 1. Interior points: vectorized central differences + 2nd-difference concavity check
  if (any(interior)) {
    idx <- which(interior)
    xi <- x[idx]
    di <- delta[idx]
    if (is.finite(L)) di <- pmin(di, 0.25 * (xi - L))
    if (is.finite(U)) di <- pmin(di, 0.25 * (U - xi))

    pts <- c(xi - di, xi + di)
    h_lr <- eval_log_density(target, pts)
    n_int <- length(idx)
    h_minus <- h_lr[seq_len(n_int)]
    h_plus <- h_lr[n_int + seq_len(n_int)]
    h_mid <- h_vals[idx]

    both_ok <- is.finite(h_minus) & is.finite(h_plus)
    if (any(both_ok)) {
      ok_i <- which(both_ok)
      hm <- h_minus[ok_i]
      hp <- h_plus[ok_i]
      h0 <- h_mid[ok_i]
      d_ok <- di[ok_i]

      h_prime[idx[ok_i]] <- (hp - hm) / (2.0 * d_ok)

      # Local second central difference: for concave h, hp - 2*h0 + hm <= 0
      d2h <- hp - 2.0 * h0 + hm
      scale_h <- pmax(1.0, abs(h0), abs(hp), abs(hm))
      if (any(d2h > 1e-10 * scale_h)) {
        stop("Non-log-concave density detected: positive second derivative of log-density.")
      }
    }

    # Fallback if an unclipped implicit support boundary caused one side to be -Inf
    if (any(!both_ok)) {
      for (k_sub in which(!both_ok)) {
        pos <- idx[k_sub]
        h_prime[pos] <- fallback_one_sided_deriv(target, x[pos], h_vals[pos], di[k_sub])
      }
    }
  }

  # 2. Exact left boundary: 2nd-order forward difference
  if (any(at_left)) {
    for (pos in which(at_left)) {
      df <- delta[pos]
      if (is.finite(U)) df <- min(df, 0.1 * (U - L))
      h_fwd <- eval_log_density(target, c(x[pos] + df, x[pos] + 2.0 * df))
      if (any(!is.finite(h_fwd))) {
        stop("Cannot compute forward derivative at lower domain boundary.")
      }
      d2h <- h_vals[pos] - 2.0 * h_fwd[1L] + h_fwd[2L]
      scale_h <- max(1.0, abs(h_vals[pos]), abs(h_fwd[1L]), abs(h_fwd[2L]))
      if (d2h > 1e-10 * scale_h) {
        stop("Non-log-concave density detected near lower domain boundary.")
      }
      h_prime[pos] <- (-3.0 * h_vals[pos] + 4.0 * h_fwd[1L] - h_fwd[2L]) / (2.0 * df)
    }
  }

  # 3. Exact right boundary: 2nd-order backward difference
  if (any(at_right)) {
    for (pos in which(at_right)) {
      db <- delta[pos]
      if (is.finite(L)) db <- min(db, 0.1 * (U - L))
      h_bwd <- eval_log_density(target, c(x[pos] - db, x[pos] - 2.0 * db))
      if (any(!is.finite(h_bwd))) {
        stop("Cannot compute backward derivative at upper domain boundary.")
      }
      d2h <- h_vals[pos] - 2.0 * h_bwd[1L] + h_bwd[2L]
      scale_h <- max(1.0, abs(h_vals[pos]), abs(h_bwd[1L]), abs(h_bwd[2L]))
      if (d2h > 1e-10 * scale_h) {
        stop("Non-log-concave density detected near upper domain boundary.")
      }
      h_prime[pos] <- (3.0 * h_vals[pos] - 4.0 * h_bwd[1L] + h_bwd[2L]) / (2.0 * db)
    }
  }

  list(h = h_vals, h_prime = h_prime)
}

#' One-sided 2nd-order finite-difference fallback near implicit support boundaries
fallback_one_sided_deriv <- function(target, x0, h0, d0) {
  # Try shrinking central difference first
  d_small <- d0 * 1e-3
  h_try <- eval_log_density(target, c(x0 - d_small, x0 + d_small))
  if (all(is.finite(h_try))) {
    return((h_try[2L] - h_try[1L]) / (2.0 * d_small))
  }
  # Forward 2nd-order difference
  h_fwd <- eval_log_density(target, c(x0 + d0, x0 + 2.0 * d0))
  if (all(is.finite(h_fwd))) {
    return((-3.0 * h0 + 4.0 * h_fwd[1L] - h_fwd[2L]) / (2.0 * d0))
  }
  # Backward 2nd-order difference
  h_bwd <- eval_log_density(target, c(x0 - d0, x0 - 2.0 * d0))
  if (all(is.finite(h_bwd))) {
    return((3.0 * h0 - 4.0 * h_bwd[1L] + h_bwd[2L]) / (2.0 * d0))
  }
  stop("Unable to evaluate finite log-density derivatives around point.")
}


# ------------------------------------------------------------------------------
# Module 3: Support Detection & Automatic Abscissa Initialization
# ------------------------------------------------------------------------------

#' Build a multi-scale search grid strictly inside domain (L, U)
build_search_grid <- function(domain) {
  L <- domain[1L]
  U <- domain[2L]

  if (is.finite(L) && is.finite(U)) {
    fracs <- sort(unique(c(
      1e-7, 1e-5, 1e-3, 0.01,
      seq(0.02, 0.98, by = 0.02),
      0.99, 1.0 - 1e-3, 1.0 - 1e-5, 1.0 - 1e-7
    )))
    return(L + (U - L) * fracs)
  }

  offsets <- sort(unique(c(
    10^seq(-7, 5, by = 0.5),
    seq(0.02, 5.0, by = 0.05),
    seq(5.5, 100.0, by = 0.5),
    seq(110.0, 1000.0, by = 10.0)
  )))

  if (is.finite(L) && !is.finite(U)) {
    return(L + offsets)
  }
  if (!is.finite(L) && is.finite(U)) {
    return(sort(U - offsets))
  }

  sort(unique(c(-offsets, 0.0, offsets)))
}

#' Detect implicit hard support boundaries via bisection when domain is unbounded
#' Distinguishes true support cutoffs (e.g. dexp at 0, dbeta at [0, 1]) from
#' smooth floating-point tail underflow (e.g. exp(-0.5 * x^2) near |x| ~ 38.6).
detect_effective_domain <- function(target, grid_x, grid_h) {
  eff_domain <- target$domain
  fin_idx <- which(is.finite(grid_h))
  if (length(fin_idx) == 0L) {
    return(eff_domain)
  }

  # Verify no zero-density gap strictly between positive-density grid points
  min_fin <- min(fin_idx)
  max_fin <- max(fin_idx)
  if (max_fin > min_fin + 1L) {
    interior_idx <- seq.int(min_fin + 1L, max_fin - 1L)
    if (any(!is.finite(grid_h[interior_idx]))) {
      stop("Non-log-concave density detected: zero-density region strictly between regions of positive support.")
    }
  }

  h_peak <- max(grid_h[fin_idx])

  # Check left implicit boundary if domain[1] == -Inf and -Inf values appear on left
  if (!is.finite(eff_domain[1L]) && min_fin > 1L) {
    lo <- grid_x[min_fin - 1L] # h == -Inf
    hi <- grid_x[min_fin]      # h is finite
    for (iter in seq_len(60L)) {
      mid <- 0.5 * (lo + hi)
      if (mid == lo || mid == hi) break
      h_mid <- eval_log_density(target, mid)
      if (is.finite(h_mid)) {
        hi <- mid
      } else {
        lo <- mid
      }
    }
    h_hi <- eval_log_density(target, hi)
    # True support boundary has h(hi) well above IEEE double underflow (-708)
    if (is.finite(h_hi) && (h_hi - h_peak > -550.0)) {
      eff_domain[1L] <- hi
    }
  }

  # Check right implicit boundary if domain[2] == +Inf and -Inf values appear on right
  if (!is.finite(eff_domain[2L]) && max_fin < length(grid_x)) {
    lo <- grid_x[max_fin]      # h is finite
    hi <- grid_x[max_fin + 1L] # h == -Inf
    for (iter in seq_len(60L)) {
      mid <- 0.5 * (lo + hi)
      if (mid == lo || mid == hi) break
      h_mid <- eval_log_density(target, mid)
      if (is.finite(h_mid)) {
        lo <- mid
      } else {
        hi <- mid
      }
    }
    h_lo <- eval_log_density(target, lo)
    if (is.finite(h_lo) && (h_lo - h_peak > -550.0)) {
      eff_domain[2L] <- lo
    }
  }

  eff_domain
}

#' Initialize starting abscissae T_k satisfying Gilks & Wild (1992) Section 2.2
initialize_abscissae <- function(target, x_init = NULL) {
  grid_x <- build_search_grid(target$domain)
  grid_h <- eval_log_density(target, grid_x)

  if (!any(is.finite(grid_h)) && is.null(x_init)) {
    stop("Invalid domain or density: could not find any point with positive finite density in 'domain'.")
  }

  # Update target with any detected finite support boundaries
  if (any(is.finite(grid_h))) {
    eff_domain <- detect_effective_domain(target, grid_x, grid_h)
    if (!is.null(x_init)) {
      eff_domain[1L] <- min(eff_domain[1L], min(x_init))
      eff_domain[2L] <- max(eff_domain[2L], max(x_init))
    }
    target$domain <- eff_domain
  }

  L <- target$domain[1L]
  U <- target$domain[2L]

  if (!is.null(x_init)) {
    h_init <- eval_log_density(target, x_init)
    if (any(!is.finite(h_init))) {
      stop("Invalid 'x_init': density must be strictly positive and finite at all initial points.")
    }
    candidates <- x_init
    # Ensure at least 5 interior check points by adding midpoints so multi-modal
    # valleys between user-supplied points are also checked
    while (length(candidates) < 5L && length(candidates) >= 2L) {
      mids <- 0.5 * (candidates[-length(candidates)] + candidates[-1L])
      candidates <- sort(unique(c(candidates, mids)))
    }
    if (length(candidates) == 1L) {
      step <- if (is.finite(L) && is.finite(U)) 0.1 * (U - L) else 0.5 * max(1.0, abs(candidates))
      extra <- c(candidates - step, candidates + step)
      extra <- extra[extra > L & extra < U]
      extra_h <- eval_log_density(target, extra)
      candidates <- sort(unique(c(candidates, extra[is.finite(extra_h)])))
    }
  } else {
    # Filter search grid to active support region within 30 log-units of peak
    in_dom <- (grid_x > L) & (grid_x < U) & is.finite(grid_h)
    if (!any(in_dom)) {
      # Re-build grid on updated effective domain
      grid_x <- build_search_grid(target$domain)
      grid_h <- eval_log_density(target, grid_x)
      in_dom <- (grid_x > L) & (grid_x < U) & is.finite(grid_h)
      if (!any(in_dom)) {
        stop("Could not locate interior points with positive finite density.")
      }
    }
    valid_x <- grid_x[in_dom]
    valid_h <- grid_h[in_dom]
    h_max <- max(valid_h)
    active_x <- valid_x[valid_h >= h_max - 25.0]
    if (length(active_x) < 5L) {
      active_x <- valid_x
    }
    if (length(active_x) < 2L) {
      x0 <- active_x[1L]
      s0 <- if (is.finite(L) && is.finite(U)) 0.05 * (U - L) else 0.1
      cand <- seq(max(L + 1e-8, x0 - 2 * s0), min(U - 1e-8, x0 + 2 * s0), length.out = 7L)
      cand_h <- eval_log_density(target, cand)
      active_x <- cand[is.finite(cand_h)]
    }
    idx_pick <- unique(round(seq(1, length(active_x), length.out = min(7L, length(active_x)))))
    candidates <- sort(unique(active_x[idx_pick]))
  }

  # Evaluate h and h' at candidate points
  hd <- compute_log_density_and_deriv(target, candidates)
  x_vec <- candidates
  h_vec <- hd$h
  hp_vec <- hd$h_prime

  # Enforce Gilks & Wild (1992) tail derivative conditions on unbounded domains:
  #   If L == -Inf, require h'(x_1) > 0
  #   If U == +Inf, require h'(x_k) < 0
  slope_min_mag <- 1e-10

  if (!is.finite(L) && hp_vec[1L] <= slope_min_mag) {
    found_left <- FALSE
    step <- max(1.0, abs(x_vec[1L]), if (length(x_vec) > 1L) diff(range(x_vec)) else 1.0)
    x_curr <- x_vec[1L]
    for (iter in seq_len(55L)) {
      x_try <- x_curr - step
      h_try <- eval_log_density(target, x_try)
      if (!is.finite(h_try)) {
        step <- step * 0.5
        if (step < 1e-12) break
        next
      }
      hd_try <- compute_log_density_and_deriv(target, x_try, h_vals = h_try)
      if (hd_try$h_prime > slope_min_mag) {
        x_vec <- c(x_try, x_vec)
        h_vec <- c(hd_try$h, h_vec)
        hp_vec <- c(hd_try$h_prime, hp_vec)
        found_left <- TRUE
        break
      }
      x_curr <- x_try
      step <- step * 2.0
    }
    if (!found_left) {
      stop("Cannot construct valid upper hull on unbounded left domain: failed to find x_1 with h'(x_1) > 0 (density may be improper or non-log-concave).")
    }
  }

  if (!is.finite(U) && hp_vec[length(hp_vec)] >= -slope_min_mag) {
    found_right <- FALSE
    step <- max(1.0, abs(x_vec[length(x_vec)]), if (length(x_vec) > 1L) diff(range(x_vec)) else 1.0)
    x_curr <- x_vec[length(x_vec)]
    for (iter in seq_len(55L)) {
      x_try <- x_curr + step
      h_try <- eval_log_density(target, x_try)
      if (!is.finite(h_try)) {
        step <- step * 0.5
        if (step < 1e-12) break
        next
      }
      hd_try <- compute_log_density_and_deriv(target, x_try, h_vals = h_try)
      if (hd_try$h_prime < -slope_min_mag) {
        x_vec <- c(x_vec, x_try)
        h_vec <- c(h_vec, hd_try$h)
        hp_vec <- c(hp_vec, hd_try$h_prime)
        found_right <- TRUE
        break
      }
      x_curr <- x_try
      step <- step * 2.0
    }
    if (!found_right) {
      stop("Cannot construct valid upper hull on unbounded right domain: failed to find x_k with h'(x_k) < 0 (density may be improper or non-log-concave).")
    }
  }

  if (length(x_vec) < 2L) {
    stop("Initialization requires at least 2 distinct valid abscissae.")
  }

  ord <- order(x_vec)
  list(
    target = target,
    x = x_vec[ord],
    h = h_vec[ord],
    h_prime = hp_vec[ord]
  )
}


# ------------------------------------------------------------------------------
# Module 4: Piecewise-Linear Hull S3 Class ("ars_hull") & Operations
# ------------------------------------------------------------------------------

#' Verify chord-tangent log-concavity conditions across sorted abscissae:
#' For concave h on x_1 < x_2 < ... < x_k with secant slopes s_j:
#'   h'(x_j) >= s_j >= h'(x_{j+1})  and  h'(x_j) >= h'(x_{j+1})
check_hull_concavity <- function(x, h, h_prime, base_tol = 1e-6) {
  k <- length(x)
  if (k < 2L) {
    return(invisible(TRUE))
  }

  dx <- diff(x)
  if (any(dx <= 0)) {
    stop("Internal hull error: abscissae must be strictly increasing.")
  }

  secant <- diff(h) / dx
  m_left <- h_prime[-k]
  m_right <- h_prime[-1L]
  h_left <- h[-k]
  h_right <- h[-1L]
  x_scale <- pmax(1.0, abs(x[-k]) + abs(x[-1L]))

  tol <- base_tol * (1.0 + abs(m_left) + abs(m_right) + (abs(h_left) + abs(h_right)) / x_scale)

  if (any(m_left < m_right - tol)) {
    stop("Non-log-concave density detected: derivative h'(x) is not monotonically non-increasing.")
  }
  if (any(m_left < secant - tol) || any(secant < m_right - tol)) {
    stop("Non-log-concave density detected: chord-tangent concavity inequality h'(x_j) >= s_j >= h'(x_{j+1}) violated.")
  }

  invisible(TRUE)
}

#' Compute log-integral of exp(h_j + (x - x_j) * m_j) over segment [a_j, b_j]
compute_segment_log_areas <- function(x, h, m, z) {
  k <- length(x)
  a <- z[-(k + 1L)]
  b <- z[-1L]
  log_areas <- rep(-Inf, k)

  for (j in seq_len(k)) {
    aj <- a[j]
    bj <- b[j]
    mj <- m[j]
    hj <- h[j]
    xj <- x[j]

    if (!is.finite(aj) && is.finite(bj)) {
      # Left unbounded tail (-Inf, b_1], requires m_1 > 0
      if (mj <= 0) {
        stop("Invalid upper hull: left tail is unbounded (-Inf) with non-positive slope.")
      }
      u_right <- hj + (bj - xj) * mj
      log_areas[j] <- u_right - log(mj)
    } else if (is.finite(aj) && !is.finite(bj)) {
      # Right unbounded tail [a_k, +Inf), requires m_k < 0
      if (mj >= 0) {
        stop("Invalid upper hull: right tail is unbounded (+Inf) with non-negative slope.")
      }
      u_left <- hj + (aj - xj) * mj
      log_areas[j] <- u_left - log(-mj)
    } else if (is.finite(aj) && is.finite(bj)) {
      wj <- bj - aj
      if (wj <= 0) {
        log_areas[j] <- -Inf
      } else {
        r <- mj * wj
        if (abs(r) < 1e-7) {
          u_mid <- hj + (0.5 * (aj + bj) - xj) * mj
          theta <- 0.5 * r
          log_areas[j] <- log(wj) + u_mid + log1p((theta * theta) / 6.0)
        } else if (r > 0) {
          u_right <- hj + (bj - xj) * mj
          log_areas[j] <- u_right - log(mj) + log1p(-exp(-r))
        } else {
          u_left <- hj + (aj - xj) * mj
          log_areas[j] <- u_left - log(-mj) + log1p(-exp(r))
        }
      }
    } else {
      stop("Invalid upper hull: single segment cannot be unbounded on both sides.")
    }
  }

  log_areas
}

#' Construct an S3 "ars_hull" object representing upper and lower hulls
#' (Gilks & Wild, 1992, Equations 1-4)
construct_hull <- function(x, h, h_prime, domain, base_tol = 1e-6) {
  k <- length(x)
  if (k < 2L) {
    stop("Hull construction requires at least 2 abscissae.")
  }

  check_hull_concavity(x, h, h_prime, base_tol = base_tol)

  dx <- diff(x)
  secant_slopes <- diff(h) / dx
  dm <- h_prime[-k] - h_prime[-1L]

  # Compute tangent intersection points z_1, ..., z_{k-1} (Gilks & Wild eq. 1)
  collinear_tol <- 1e-11 * (1.0 + abs(h_prime[-k]) + abs(h_prime[-1L]))
  z_inner <- numeric(k - 1L)

  collinear <- dm <= collinear_tol
  if (any(collinear)) {
    z_inner[collinear] <- 0.5 * (x[-k][collinear] + x[-1L][collinear])
  }
  if (any(!collinear)) {
    nc <- !collinear
    frac <- (secant_slopes[nc] - h_prime[-1L][nc]) / dm[nc]
    frac <- pmin(pmax(frac, 0.0), 1.0)
    z_inner[nc] <- x[-k][nc] + dx[nc] * frac
  }

  z <- c(domain[1L], z_inner, domain[2L])
  log_areas <- compute_segment_log_areas(x, h, h_prime, z)
  log_total_area <- log_sum_exp(log_areas)
  if (!is.finite(log_total_area)) {
    stop("Invalid upper hull: total integral of upper envelope is not finite.")
  }

  probs <- exp(log_areas - log_total_area)
  probs_sum <- sum(probs)
  if (!is.finite(probs_sum) || probs_sum <= 0) {
    stop("Invalid upper hull: failed to normalize piecewise segment probabilities.")
  }
  probs <- probs / probs_sum

  structure(
    list(
      k = k,
      x = x,
      h = h,
      h_prime = h_prime,
      secant_slopes = secant_slopes,
      z = z,
      log_areas = log_areas,
      log_total_area = log_total_area,
      probs = probs,
      domain = domain
    ),
    class = "ars_hull"
  )
}

#' S3 print method for ars_hull
print.ars_hull <- function(x, ...) {
  cat(sprintf(
    "<ars_hull> k = %d abscissae on [%s, %s], log_envelope_integral = %.6f\n",
    x$k, format(x$domain[1L]), format(x$domain[2L]), x$log_total_area
  ))
  invisible(x)
}

#' S3 summary method for ars_hull
summary.ars_hull <- function(object, ...) {
  list(
    num_abscissae = object$k,
    domain = object$domain,
    abscissae_range = range(object$x),
    log_total_area = object$log_total_area,
    max_segment_prob = max(object$probs)
  )
}

#' Evaluate piecewise-linear upper hull u_k(x) at arbitrary points
eval_upper_hull <- function(hull, x_eval) {
  if (length(x_eval) == 0L) {
    return(numeric(0L))
  }
  # Partition points z_0, z_1, ..., z_k; assign x_eval to segment j in 1..k
  z_internal <- hull$z[-c(1L, hull$k + 1L)]
  seg <- findInterval(x_eval, z_internal) + 1L
  hull$h[seg] + (x_eval - hull$x[seg]) * hull$h_prime[seg]
}

#' Evaluate piecewise-linear squeezing lower hull l_k(x) (Gilks & Wild eq. 4)
#' Returns -Inf for x < x_1 or x > x_k.
eval_lower_hull <- function(hull, x_eval) {
  n_eval <- length(x_eval)
  if (n_eval == 0L) {
    return(numeric(0L))
  }

  l_val <- rep(-Inf, n_eval)
  x1 <- hull$x[1L]
  xk <- hull$x[hull$k]

  inside <- (x_eval >= x1) & (x_eval <= xk)
  if (!any(inside)) {
    return(l_val)
  }

  x_in <- x_eval[inside]
  idx <- findInterval(x_in, hull$x, rightmost.closed = TRUE)
  idx <- pmin(pmax(idx, 1L), hull$k - 1L)
  l_val[inside] <- hull$h[idx] + (x_in - hull$x[idx]) * hull$secant_slopes[idx]
  l_val
}

#' Draw m exact samples from the normalized upper hull s_k(x) proportional to exp(u_k(x))
sample_upper_hull <- function(hull, m = 1L) {
  seg <- sample.int(hull$k, size = m, replace = TRUE, prob = hull$probs)
  v <- stats::runif(m)
  # Clamp uniform away from exact 0 and 1 to avoid log(0)
  v <- pmin(pmax(v, .Machine$double.xmin), 1.0 - .Machine$double.eps)

  a <- hull$z[seg]
  b <- hull$z[seg + 1L]
  slope <- hull$h_prime[seg]
  xj <- hull$x[seg]
  hj <- hull$h[seg]

  x_star <- numeric(m)

  left_inf <- !is.finite(a) & is.finite(b)
  right_inf <- is.finite(a) & !is.finite(b)
  both_fin <- is.finite(a) & is.finite(b)

  if (any(left_inf)) {
    x_star[left_inf] <- b[left_inf] + log(v[left_inf]) / slope[left_inf]
  }
  if (any(right_inf)) {
    x_star[right_inf] <- a[right_inf] + log(v[right_inf]) / slope[right_inf]
  }
  if (any(both_fin)) {
    idx <- which(both_fin)
    af <- a[idx]
    bf <- b[idx]
    sf <- slope[idx]
    vf <- v[idx]
    wf <- bf - af
    rf <- sf * wf

    xf <- numeric(length(idx))
    near_flat <- abs(rf) < 1e-8
    pos_r <- (!near_flat) & (rf > 0)
    neg_r <- (!near_flat) & (rf < 0)

    if (any(near_flat)) {
      nf <- near_flat
      xf[nf] <- af[nf] + wf[nf] * (vf[nf] - 0.5 * rf[nf] * vf[nf] * (1.0 - vf[nf]))
    }
    if (any(pos_r)) {
      pr <- pos_r
      log_term <- log_add_exp(log(vf[pr]), log(1.0 - vf[pr]) - rf[pr])
      xf[pr] <- bf[pr] + log_term / sf[pr]
    }
    if (any(neg_r)) {
      nr <- neg_r
      qf <- -rf[nr]
      log_term <- log_add_exp(log(1.0 - vf[nr]), log(vf[nr]) - qf)
      xf[nr] <- af[nr] + log_term / sf[nr]
    }

    xf <- pmin(pmax(xf, af), bf)
    x_star[idx] <- xf
  }

  u_val <- hj + (x_star - xj) * slope
  list(x = x_star, seg = seg, u = u_val)
}

#' Insert a new abscissa (x_new, h_new, h_prime_new) into an existing ars_hull
insert_abscissa <- function(hull, x_new, h_new, h_prime_new, base_tol = 1e-6) {
  pos <- findInterval(x_new, hull$x)
  new_x <- append(hull$x, x_new, after = pos)
  new_h <- append(hull$h, h_new, after = pos)
  new_hp <- append(hull$h_prime, h_prime_new, after = pos)
  construct_hull(new_x, new_h, new_hp, domain = hull$domain, base_tol = base_tol)
}


# ------------------------------------------------------------------------------
# Module 5: Sampling & Runtime Log-Concavity Verification
# ------------------------------------------------------------------------------

#' Verify envelope log-concavity inequality l_k(x*) <= h(x*) <= u_k(x*) during sampling
check_envelope_concavity <- function(h_star, l_star, u_star, base_tol = 1e-6) {
  scale_val <- 1.0 + abs(u_star) + ifelse(is.finite(h_star), abs(h_star), 0.0)
  env_tol <- base_tol * scale_val

  if (any(h_star > u_star + env_tol)) {
    stop("Non-log-concave density detected during sampling: log-density h(x*) exceeded upper hull u_k(x*).")
  }

  has_lower <- is.finite(l_star)
  if (any(has_lower)) {
    # If h_star is -Inf strictly inside [x_1, x_k], l_star is finite so h_star < l_star - env_tol is TRUE!
    if (any(h_star[has_lower] < l_star[has_lower] - env_tol[has_lower])) {
      stop("Non-log-concave density detected during sampling: log-density h(x*) fell below lower hull l_k(x*).")
    }
  }

  invisible(TRUE)
}

#' Core Gilks & Wild (1992) Adaptive Rejection Sampling Loop
ars_sample_loop <- function(target,
                            hull,
                            n,
                            max_points = 100L,
                            min_adapt_points = 15L,
                            base_tol = 1e-6) {
  samples <- numeric(n)
  n_acc <- 0L
  n_proposals <- 0L
  max_proposals <- max(200000L, 200L * n)

  # Phase 1: Step-by-step adaptive rejection sampling while hull adapts (k < max_points)
  while (n_acc < n && hull$k < max_points) {
    n_proposals <- n_proposals + 1L
    if (n_proposals > max_proposals) {
      stop("Adaptive rejection sampler exceeded maximum proposal limit without converging.")
    }

    prop <- sample_upper_hull(hull, m = 1L)
    x_star <- prop$x
    u_star <- prop$u
    l_star <- eval_lower_hull(hull, x_star)

    w <- max(stats::runif(1L), .Machine$double.xmin)
    log_w <- log(w)

    # Enable squeeze shortcut once hull has at least min_adapt_points abscissae
    # so early proposals thoroughly verify log-concavity across the domain
    if (hull$k >= min_adapt_points && is.finite(l_star) && (log_w <= l_star - u_star)) {
      n_acc <- n_acc + 1L
      samples[n_acc] <- x_star
      next
    }

    # Evaluate true log-density h(x*)
    h_star <- eval_log_density(target, x_star)

    # Runtime log-concavity check: l_k(x*) <= h(x*) <= u_k(x*)
    check_envelope_concavity(h_star, l_star, u_star, base_tol = base_tol)

    # Rejection test
    if (is.finite(h_star) && (log_w <= h_star - u_star)) {
      n_acc <- n_acc + 1L
      samples[n_acc] <- x_star
    }

    # Updating step (Gilks & Wild Section 2.2): insert x* into T_k if well-separated
    if (is.finite(h_star)) {
      min_dist <- min(abs(x_star - hull$x))
      if (min_dist > 1e-4 * max(1.0, abs(x_star))) {
        hd_new <- compute_log_density_and_deriv(target, x_star, h_vals = h_star)
        hull <- insert_abscissa(hull, x_star, hd_new$h, hd_new$h_prime, base_tol = base_tol)
      }
    }
  }

  # Phase 2: Vectorized sampling once hull has reached max_points abscissae,
  # maintaining full runtime envelope & tail log-concavity verification.
  while (n_acc < n) {
    rem <- n - n_acc
    batch_size <- max(64L, as.integer(ceiling(1.05 * rem)))
    n_proposals <- n_proposals + batch_size
    if (n_proposals > max_proposals) {
      stop("Adaptive rejection sampler exceeded maximum proposal limit without converging.")
    }

    prop <- sample_upper_hull(hull, m = batch_size)
    x_batch <- prop$x
    u_batch <- prop$u
    l_batch <- eval_lower_hull(hull, x_batch)

    w_batch <- pmax(stats::runif(batch_size), .Machine$double.xmin)
    log_w_batch <- log(w_batch)

    squeezed <- is.finite(l_batch) & (log_w_batch <= l_batch - u_batch)
    accepted <- squeezed

    unsqueezed_idx <- which(!squeezed)
    if (length(unsqueezed_idx) > 0L) {
      x_unsq <- x_batch[unsqueezed_idx]
      u_unsq <- u_batch[unsqueezed_idx]
      l_unsq <- l_batch[unsqueezed_idx]
      h_unsq <- eval_log_density(target, x_unsq)

      # Runtime log-concavity check on all evaluated proposals
      check_envelope_concavity(h_unsq, l_unsq, u_unsq, base_tol = base_tol)

      # Also check derivative concavity for any proposals in the outer tails
      tail_mask <- is.finite(h_unsq) & ((x_unsq < hull$x[1L]) | (x_unsq > hull$x[hull$k]))
      if (any(tail_mask)) {
        for (t_i in which(tail_mask)) {
          xt <- x_unsq[t_i]
          ht <- h_unsq[t_i]
          if (min(abs(xt - hull$x)) > 1e-4 * max(1.0, abs(xt))) {
            hd_t <- compute_log_density_and_deriv(target, xt, h_vals = ht)
            hull <- insert_abscissa(hull, xt, hd_t$h, hd_t$h_prime, base_tol = base_tol)
          }
        }
      }

      accepted[unsqueezed_idx] <- is.finite(h_unsq) & (log_w_batch[unsqueezed_idx] <= h_unsq - u_unsq)
    }

    acc_x <- x_batch[accepted]
    n_take <- min(rem, length(acc_x))
    if (n_take > 0L) {
      samples[(n_acc + 1L):(n_acc + n_take)] <- acc_x[seq_len(n_take)]
      n_acc <- n_acc + n_take
    }
  }

  samples
}


# ------------------------------------------------------------------------------
# Module 6: Primary User-Facing Function `ars()`
# ------------------------------------------------------------------------------

#' Adaptive Rejection Sampler (Gilks & Wild, 1992)
#'
#' Draws independent samples from a univariate log-concave density (possibly
#' unnormalized) using Adaptive Rejection Sampling.
#'
#' @param f A vectorized density function (e.g., dnorm, dexp), R expression in x,
#'   or single character string naming a density function.
#' @param n Positive integer number of samples to draw (default: 1000L).
#' @param domain Numeric vector c(lower, upper) specifying support bounds
#'   (default: c(-Inf, Inf)).
#' @param x_init Optional numeric vector of initial abscissae inside domain.
#' @param lower Optional scalar overriding domain[1].
#' @param upper Optional scalar overriding domain[2].
#' @param bounds Optional length-2 numeric vector alias for domain.
#' @param max_points Maximum number of hull abscissae before fixing interior
#'   adaptation (default: 100L).
#' @param eps Relative finite-difference step size for log-density derivatives
#'   (default: 1e-6).
#' @param ... Additional arguments passed to f when f is a function.
#' @return Numeric vector of length n containing independent draws from f.
ars <- function(f,
                n = 1000L,
                domain = c(-Inf, Inf),
                x_init = NULL,
                lower = NULL,
                upper = NULL,
                bounds = NULL,
                max_points = 100L,
                eps = 1e-6,
                ...) {
  eval_env <- parent.frame()
  extra_args <- list(...)

  validated <- validate_ars_inputs(
    f = f,
    n = n,
    domain = domain,
    x_init = x_init,
    lower = lower,
    upper = upper,
    bounds = bounds,
    max_points = max_points,
    eps = eps,
    extra_args = extra_args,
    eval_env = eval_env
  )

  init_state <- initialize_abscissae(validated$target, x_init = validated$x_init)
  hull <- construct_hull(
    x = init_state$x,
    h = init_state$h,
    h_prime = init_state$h_prime,
    domain = init_state$target$domain
  )

  ars_sample_loop(
    target = init_state$target,
    hull = hull,
    n = validated$n,
    max_points = init_state$target$max_points
  )
}


# ------------------------------------------------------------------------------
# Module 7: Formal Testing Suite `test()`
# ------------------------------------------------------------------------------

#' Format and record a single formal test result
record_test_result <- function(results_env,
                               test_name,
                               passed,
                               sample_mean = NA_real_,
                               expected_mean = NA_real_,
                               sample_sd = NA_real_,
                               expected_sd = NA_real_,
                               note = "") {
  status_str <- if (isTRUE(passed)) "PASS" else "FAIL"

  if (is.finite(sample_mean) && is.finite(sample_sd)) {
    if (is.finite(expected_mean) && is.finite(expected_sd)) {
      stat_msg <- sprintf(
        "mean = %.4f (expected = %.4f), sd = %.4f (expected = %.4f)%s",
        sample_mean, expected_mean, sample_sd, expected_sd,
        if (nzchar(note)) paste0(", ", note) else ""
      )
    } else {
      stat_msg <- sprintf(
        "mean = %.4f, sd = %.4f%s",
        sample_mean, sample_sd,
        if (nzchar(note)) paste0(", ", note) else ""
      )
    }
  } else {
    stat_msg <- sprintf(
      "mean = NA, sd = NA%s",
      if (nzchar(note)) paste0(" [", note, "]") else ""
    )
  }

  cat(sprintf("%s: %s | %s\n", test_name, status_str, stat_msg))

  results_env$rows[[length(results_env$rows) + 1L]] <- data.frame(
    test_name = test_name,
    passed = isTRUE(passed),
    sample_mean = sample_mean,
    expected_mean = expected_mean,
    sample_sd = sample_sd,
    expected_sd = expected_sd,
    note = note,
    stringsAsFactors = FALSE
  )
}

#' Run a formal stochastic goodness-of-fit & moment test on a known distribution
run_distribution_test <- function(results_env,
                                  test_name,
                                  description,
                                  sampler_fn,
                                  true_mean,
                                  true_sd,
                                  cdf_fn = NULL,
                                  z_tol = 4.0,
                                  sd_rel_tol = 0.06,
                                  ks_alpha = 0.005) {
  cat(sprintf("\n[Testing Distribution] %s\n", description))

  draws <- tryCatch(
    sampler_fn(),
    error = function(e) {
      record_test_result(
        results_env, test_name, FALSE,
        expected_mean = true_mean, expected_sd = true_sd,
        note = paste("Unexpected error:", conditionMessage(e))
      )
      return(NULL)
    }
  )
  if (is.null(draws)) {
    return(invisible(NULL))
  }

  n_draws <- length(draws)
  s_mean <- mean(draws)
  s_sd <- stats::sd(draws)

  # Monte Carlo Z-score for sample mean: |X_bar - mu| / (sigma / sqrt(n))
  mean_se <- true_sd / sqrt(n_draws)
  z_score <- abs(s_mean - true_mean) / mean_se
  sd_rel_err <- abs(s_sd - true_sd) / true_sd

  ks_pval <- NA_real_
  ks_ok <- TRUE
  if (!is.null(cdf_fn)) {
    ks_res <- suppressWarnings(stats::ks.test(draws, cdf_fn))
    ks_pval <- ks_res$p.value
    ks_ok <- is.finite(ks_pval) && (ks_pval > ks_alpha)
  }

  passed <- is.finite(s_mean) && is.finite(s_sd) &&
    (z_score < z_tol) && (sd_rel_err < sd_rel_tol) && ks_ok

  note_str <- if (!is.null(cdf_fn)) {
    sprintf("|Z_mean| = %.2f, KS p-value = %.4f", z_score, ks_pval)
  } else {
    sprintf("|Z_mean| = %.2f, rel_sd_err = %.4f", z_score, sd_rel_err)
  }

  record_test_result(
    results_env,
    test_name = test_name,
    passed = passed,
    sample_mean = s_mean,
    expected_mean = true_mean,
    sample_sd = s_sd,
    expected_sd = true_sd,
    note = note_str
  )

  invisible(draws)
}

#' Verify that an invalid or non-log-concave call cleanly raises an error
run_error_expectation_test <- function(results_env, test_name, description, expr_fn) {
  cat(sprintf("\n[Testing Error Handling] %s\n", description))
  caught_msg <- NULL
  errored <- tryCatch(
    {
      expr_fn()
      FALSE
    },
    error = function(e) {
      caught_msg <<- conditionMessage(e)
      TRUE
    }
  )

  note <- if (errored) {
    sprintf("Caught expected error: %s", caught_msg)
  } else {
    "Expected an error, but call succeeded without error"
  }

  record_test_result(results_env, test_name = test_name, passed = errored, note = note)
}

#' Formal Test Suite for Adaptive Rejection Sampler and Internal Modules
#'
#' Executes unit tests on internal modules, stochastic distribution shape/moment
#' tests against analytical truth, runtime non-log-concavity detection tests,
#' and input validation tests. Also writes sample output files to /app.
#'
#' @param n_samples Number of draws per distribution test (default: 10000L).
#' @param seed Integer RNG seed for reproducible stochastic verification (default: 2026L).
#' @param save_samples Logical; if TRUE, writes normal and exponential samples to disk.
#' @param output_dir Directory where sample files are saved (default: "/app").
#' @return Invisibly returns a data.frame summarizing all test outcomes.
test <- function(n_samples = 10000L,
                 seed = 2026L,
                 save_samples = TRUE,
                 output_dir = "/app") {
  set.seed(seed)
  results_env <- new.env(parent = emptyenv())
  results_env$rows <- list()

  cat("==============================================================================\n")
  cat("Adaptive Rejection Sampler (Gilks & Wild, 1992) - Formal Test Suite\n")
  cat(sprintf("Configuration: n_samples = %d, seed = %d\n", n_samples, seed))
  cat("==============================================================================\n")

  # ----------------------------------------------------------------------------
  # Section A: Modular Component Unit Tests
  # ----------------------------------------------------------------------------
  cat("\n--- Section 1: Internal Module Unit Tests ---\n")

  # Module Test 1: Numerical log-density & derivative accuracy (interior + boundary)
  cat("\n[Testing Module] Numerical log-density and derivative accuracy on Gamma(3, 2)...\n")
  mod1_ok <- tryCatch({
    v_mod1 <- validate_ars_inputs(
      f = stats::dgamma, n = 10L, domain = c(0, Inf),
      extra_args = list(shape = 3, rate = 2), eval_env = environment()
    )
    pts <- c(1e-4, 0.25, 1.0, 2.5, 6.0)
    hd <- compute_log_density_and_deriv(v_mod1$target, pts)
    true_h <- stats::dgamma(pts, shape = 3, rate = 2, log = TRUE)
    true_hp <- 2.0 / pts - 2.0
    err_h <- max(abs(hd$h - true_h))
    err_hp <- max(abs(hd$h_prime - true_hp))
    list(ok = (err_h < 1e-12) && (err_hp < 1e-5), vals = hd$h_prime, exp_vals = true_hp, err = err_hp)
  }, error = function(e) list(ok = FALSE, vals = NA_real_, exp_vals = NA_real_, err = Inf))

  record_test_result(
    results_env, "TEST_MODULE_DERIVATIVE", mod1_ok$ok,
    sample_mean = mean(mod1_ok$vals), expected_mean = mean(mod1_ok$exp_vals),
    sample_sd = stats::sd(mod1_ok$vals), expected_sd = stats::sd(mod1_ok$exp_vals),
    note = sprintf("max |h' - true_h'| = %.2e", mod1_ok$err)
  )

  # Module Test 2: Exact hull tangent intersections, log-areas, and envelope bounds
  cat("\n[Testing Module] Piecewise-linear hull intersections, areas, and l(x) <= h(x) <= u(x)...\n")
  x_kn <- c(-2.0, 0.0, 2.0)
  h_kn <- -0.5 * x_kn^2
  hp_kn <- -x_kn
  hull_kn <- construct_hull(x_kn, h_kn, hp_kn, domain = c(-Inf, Inf))
  # Analytical truth for h(x) = -0.5 x^2 at (-2, 0, 2):
  # z = (-Inf, -1, 1, Inf), areas = (0.5, 2.0, 0.5), total = 3.0, probs = (1/6, 4/6, 1/6)
  z_err <- max(abs(hull_kn$z[2:3] - c(-1.0, 1.0)))
  prob_err <- max(abs(hull_kn$probs - c(1 / 6, 4 / 6, 1 / 6)))
  area_err <- abs(exp(hull_kn$log_total_area) - 3.0)
  grid_chk <- seq(-5, 5, length.out = 501L)
  u_chk <- eval_upper_hull(hull_kn, grid_chk)
  l_chk <- eval_lower_hull(hull_kn, grid_chk)
  h_chk <- -0.5 * grid_chk^2
  env_ok <- all(u_chk >= h_chk - 1e-12) && all(l_chk <= h_chk + 1e-12)
  mod2_ok <- (z_err < 1e-12) && (prob_err < 1e-12) && (area_err < 1e-12) && env_ok

  record_test_result(
    results_env, "TEST_MODULE_HULL_GEOMETRY", mod2_ok,
    sample_mean = mean(u_chk), expected_mean = mean(u_chk),
    sample_sd = stats::sd(u_chk), expected_sd = stats::sd(u_chk),
    note = sprintf("z_err = %.2e, prob_err = %.2e, area_err = %.2e", z_err, prob_err, area_err)
  )

  # Module Test 3: Upper-hull piecewise-exponential exact sampler moments
  # For s_3(x) with z = (-Inf, -1, 1, Inf), p = (1/6, 4/6, 1/6), slopes = (2, 0, -2):
  # Exact mean = 0, exact variance = (1/6)*2.5 + (4/6)*(1/3) + (1/6)*2.5 = 19/18
  cat("\n[Testing Module] Sampling directly from piecewise-exponential upper hull s_k(x)...\n")
  hull_draws <- sample_upper_hull(hull_kn, m = 20000L)$x
  true_hull_sd <- sqrt(19.0 / 18.0)
  hull_z <- abs(mean(hull_draws) - 0.0) / (true_hull_sd / sqrt(20000L))
  hull_sd_err <- abs(stats::sd(hull_draws) - true_hull_sd) / true_hull_sd
  mod3_ok <- (hull_z < 4.0) && (hull_sd_err < 0.04)

  record_test_result(
    results_env, "TEST_MODULE_HULL_SAMPLER", mod3_ok,
    sample_mean = mean(hull_draws), expected_mean = 0.0,
    sample_sd = stats::sd(hull_draws), expected_sd = true_hull_sd,
    note = sprintf("|Z_mean| = %.2f, rel_sd_err = %.4f", hull_z, hull_sd_err)
  )

  # Module Test 4: Adaptive hull insertion tightens upper envelope integral monotonically
  cat("\n[Testing Module] Adaptive abscissa insertion and envelope tightening...\n")
  hull_upd <- insert_abscissa(hull_kn, x_new = 1.0, h_new = -0.5, h_prime_new = -1.0)
  mod4_ok <- (hull_upd$k == 4L) &&
    isTRUE(all.equal(hull_upd$x, c(-2.0, 0.0, 1.0, 2.0))) &&
    (hull_upd$log_total_area < hull_kn$log_total_area)

  record_test_result(
    results_env, "TEST_MODULE_HULL_UPDATE", mod4_ok,
    sample_mean = mean(hull_upd$x), expected_mean = 0.25,
    sample_sd = stats::sd(hull_upd$x), expected_sd = stats::sd(c(-2.0, 0.0, 1.0, 2.0)),
    note = sprintf("area tightened from %.4f to %.4f", exp(hull_kn$log_total_area), exp(hull_upd$log_total_area))
  )

  # Module Test 5: Automatic abscissa & support initialization without user hints
  cat("\n[Testing Module] Automatic initialization on shifted Normal N(45, 0.5^2) and Beta(2, 5)...\n")
  v_shift <- validate_ars_inputs(
    stats::dnorm, n = 10L, domain = c(-Inf, Inf),
    extra_args = list(mean = 45, sd = 0.5), eval_env = environment()
  )
  init_shift <- initialize_abscissae(v_shift$target)
  v_beta <- validate_ars_inputs(
    stats::dbeta, n = 10L, domain = c(-Inf, Inf),
    extra_args = list(shape1 = 2, shape2 = 5), eval_env = environment()
  )
  init_beta <- initialize_abscissae(v_beta$target)
  mod5_ok <- (init_shift$h_prime[1L] > 0) &&
    (init_shift$h_prime[length(init_shift$h_prime)] < 0) &&
    (abs(init_beta$target$domain[1L] - 0.0) < 1e-6) &&
    (abs(init_beta$target$domain[2L] - 1.0) < 1e-6)

  record_test_result(
    results_env, "TEST_MODULE_INITIALIZATION", mod5_ok,
    sample_mean = mean(init_shift$x), expected_mean = 45.0,
    sample_sd = stats::sd(init_shift$x), expected_sd = stats::sd(init_shift$x),
    note = sprintf("detected Beta support = [%.6f, %.6f]", init_beta$target$domain[1L], init_beta$target$domain[2L])
  )

  # ----------------------------------------------------------------------------
  # Section B: Known Log-Concave Distributions (End-to-End Stochastic Tests)
  # ----------------------------------------------------------------------------
  cat("\n--- Section 2: Known Log-Concave Distribution Tests ---\n")

  norm_draws <- run_distribution_test(
    results_env,
    test_name = "TEST_STANDARD_NORMAL",
    description = "Standard Normal N(0, 1) via ars(dnorm, n)",
    sampler_fn = function() ars(stats::dnorm, n = n_samples),
    true_mean = 0.0,
    true_sd = 1.0,
    cdf_fn = stats::pnorm
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_SHIFTED_NORMAL",
    description = "Shifted & Scaled Normal N(mean = 12, sd = 2.5) via extra '...' parameters",
    sampler_fn = function() ars(stats::dnorm, n = n_samples, mean = 12, sd = 2.5),
    true_mean = 12.0,
    true_sd = 2.5,
    cdf_fn = function(q) stats::pnorm(q, mean = 12, sd = 2.5)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_TRUNCATED_HALF_NORMAL",
    description = "Half-Normal (Standard Normal truncated to [0, Inf))",
    sampler_fn = function() ars(stats::dnorm, n = n_samples, domain = c(0, Inf)),
    true_mean = sqrt(2.0 / pi),
    true_sd = sqrt(1.0 - 2.0 / pi),
    cdf_fn = function(q) ifelse(q < 0, 0, 2.0 * stats::pnorm(q) - 1.0)
  )

  exp_draws <- run_distribution_test(
    results_env,
    test_name = "TEST_STANDARD_EXPONENTIAL",
    description = "Standard Exponential Exp(rate = 1) on [0, Inf)",
    sampler_fn = function() ars(stats::dexp, n = n_samples, domain = c(0, Inf)),
    true_mean = 1.0,
    true_sd = 1.0,
    cdf_fn = stats::pexp
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_EXPONENTIAL_AUTO_DOMAIN",
    description = "Exponential Exp(rate = 2.5) without explicit domain (automatic support detection)",
    sampler_fn = function() ars(stats::dexp, n = n_samples, rate = 2.5),
    true_mean = 0.4,
    true_sd = 0.4,
    cdf_fn = function(q) stats::pexp(q, rate = 2.5)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_GAMMA_DISTRIBUTION",
    description = "Gamma(shape = 3, rate = 2) on [0, Inf)",
    sampler_fn = function() ars(stats::dgamma, n = n_samples, domain = c(0, Inf), shape = 3, rate = 2),
    true_mean = 1.5,
    true_sd = sqrt(3.0) / 2.0,
    cdf_fn = function(q) stats::pgamma(q, shape = 3, rate = 2)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_BETA_DISTRIBUTION",
    description = "Beta(shape1 = 2, shape2 = 5) on compact support [0, 1]",
    sampler_fn = function() ars(stats::dbeta, n = n_samples, domain = c(0, 1), shape1 = 2, shape2 = 5),
    true_mean = 2.0 / 7.0,
    true_sd = sqrt((2.0 * 5.0) / (49.0 * 8.0)),
    cdf_fn = function(q) stats::pbeta(q, shape1 = 2, shape2 = 5)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_UNIFORM_DISTRIBUTION",
    description = "Uniform(-2, 4) log-flat density on [-2, 4]",
    sampler_fn = function() ars(stats::dunif, n = n_samples, domain = c(-2, 4), min = -2, max = 4),
    true_mean = 1.0,
    true_sd = 6.0 / sqrt(12.0),
    cdf_fn = function(q) stats::punif(q, min = -2, max = 4)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_LOGISTIC_DISTRIBUTION",
    description = "Standard Logistic(0, 1) distribution",
    sampler_fn = function() ars(stats::dlogis, n = n_samples),
    true_mean = 0.0,
    true_sd = pi / sqrt(3.0),
    cdf_fn = stats::plogis
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_UNNORMALIZED_DENSITY",
    description = "Unnormalized Laplace density f(x) = 37.5 * exp(-|x - 2|) with arbitrary scale",
    sampler_fn = function() ars(function(x) 37.5 * exp(-abs(x - 2.0)), n = n_samples),
    true_mean = 2.0,
    true_sd = sqrt(2.0),
    cdf_fn = function(q) ifelse(q < 2.0, 0.5 * exp(q - 2.0), 1.0 - 0.5 * exp(-(q - 2.0)))
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_EXPRESSION_INPUT",
    description = "R expression input expression(exp(-0.5 * (x - 3)^2)) for unnormalized N(3, 1)",
    sampler_fn = function() ars(expression(exp(-0.5 * (x - 3)^2)), n = n_samples),
    true_mean = 3.0,
    true_sd = 1.0,
    cdf_fn = function(q) stats::pnorm(q, mean = 3.0, sd = 1.0)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_EXTREME_UNNORMALIZED_SCALE",
    description = "Extreme small scale f(x) = 1e-150 * exp(-0.5 * x^2) testing log-space stability",
    sampler_fn = function() ars(function(x) 1e-150 * exp(-0.5 * x^2), n = n_samples),
    true_mean = 0.0,
    true_sd = 1.0,
    cdf_fn = stats::pnorm
  )

  # ----------------------------------------------------------------------------
  # Section C: Non-Log-Concave Density Detection (Initialization & Runtime)
  # ----------------------------------------------------------------------------
  cat("\n--- Section 3: Non-Log-Concave Density Detection Tests ---\n")

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_CAUCHY_RUNTIME",
    description = "Cauchy initialized on locally log-concave core [-0.4, 0, 0.4] (must catch during sampling)",
    expr_fn = function() ars(stats::dcauchy, n = 500L, x_init = c(-0.4, -0.2, 0.0, 0.2, 0.4))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_STUDENT_T_RUNTIME",
    description = "Student-t(df = 2) initialized inside locally concave core [-0.5, 0.5] (caught during sampling)",
    expr_fn = function() ars(stats::dt, n = 500L, df = 2, x_init = c(-0.5, -0.25, 0.0, 0.25, 0.5))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_BIMODAL_MIXTURE",
    description = "Bimodal Gaussian mixture 0.5*N(-3, 1) + 0.5*N(3, 1)",
    expr_fn = function() ars(function(x) 0.5 * stats::dnorm(x, -3, 1) + 0.5 * stats::dnorm(x, 3, 1), n = 500L)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_GAMMA_SUBUNITY",
    description = "Gamma(shape = 0.5, rate = 1) which is strictly log-convex on (0, Inf)",
    expr_fn = function() ars(stats::dgamma, n = 200L, domain = c(0, Inf), shape = 0.5, rate = 1)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_BETA_USHAPED",
    description = "U-shaped Beta(0.5, 0.5) which is log-convex on (0, 1)",
    expr_fn = function() ars(stats::dbeta, n = 200L, domain = c(0, 1), shape1 = 0.5, shape2 = 0.5)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_LOGNORMAL",
    description = "Log-normal distribution dlnorm (heavy non-log-concave right tail)",
    expr_fn = function() ars(stats::dlnorm, n = 500L, domain = c(0, Inf))
  )

  # ----------------------------------------------------------------------------
  # Section D: Input Validation Error Handling Tests
  # ----------------------------------------------------------------------------
  cat("\n--- Section 4: Input Validation & Error Handling Tests ---\n")

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_NEGATIVE_N",
    description = "Reject negative sample count n = -10",
    expr_fn = function() ars(stats::dnorm, n = -10)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_ZERO_OR_NONINT_N",
    description = "Reject non-integer sample count n = 3.5",
    expr_fn = function() ars(stats::dnorm, n = 3.5)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_DOMAIN_ORDER",
    description = "Reject inverted domain c(5, -2) where lower >= upper",
    expr_fn = function() ars(stats::dnorm, n = 100, domain = c(5, -2))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_ZERO_DENSITY_DOMAIN",
    description = "Reject domain c(-10, -1) where Exponential density is identically zero",
    expr_fn = function() ars(stats::dexp, n = 100, domain = c(-10, -1))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_NONVECTORIZED_FN",
    description = "Reject non-vectorized function returning scalar of wrong length",
    expr_fn = function() ars(function(x) 1.0, n = 100, domain = c(0, 1))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_NEGATIVE_DENSITY",
    description = "Reject function that evaluates to negative values",
    expr_fn = function() ars(function(x) -stats::dnorm(x), n = 100)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_XINIT_OUT_OF_DOMAIN",
    description = "Reject x_init containing points outside specified domain",
    expr_fn = function() ars(stats::dnorm, n = 100, domain = c(0, Inf), x_init = c(-1, 1, 2))
  )

  # ----------------------------------------------------------------------------
  # Save generated samples to /app/normal_samples.txt & /app/exponential_samples.txt
  # ----------------------------------------------------------------------------
  if (isTRUE(save_samples) && dir.exists(output_dir)) {
    if (!is.null(norm_draws)) {
      norm_path <- file.path(output_dir, "normal_samples.txt")
      write(norm_draws, file = norm_path, ncolumns = 1L)
      cat(sprintf("\nSaved %d standard normal ARS samples to %s\n", length(norm_draws), norm_path))
    }
    if (!is.null(exp_draws)) {
      exp_path <- file.path(output_dir, "exponential_samples.txt")
      write(exp_draws, file = exp_path, ncolumns = 1L)
      cat(sprintf("Saved %d standard exponential ARS samples to %s\n", length(exp_draws), exp_path))
    }
  }

  summary_df <- do.call(rbind, results_env$rows)
  n_total <- nrow(summary_df)
  n_pass <- sum(summary_df$passed)

  cat("\n==============================================================================\n")
  if (n_pass == n_total) {
    cat(sprintf("OVERALL RESULT: ALL %d TESTS PASSED (%d/%d)\n", n_total, n_pass, n_total))
  } else {
    cat(sprintf("OVERALL RESULT: %d/%d TESTS PASSED (%d UNEXPECTED OUTCOMES)\n", n_pass, n_total, n_total - n_pass))
  }
  cat("==============================================================================\n")

  invisible(summary_df)
}

