#' Format and record a single formal test result
record_test_result <- function(results_env,
                               test_name,
                               passed,
                               sample_mean = NA_real_,
                               expected_mean = NA_real_,
                               sample_sd = NA_real_,
                               expected_sd = NA_real_,
                               note = "") {
  status_str <- if (isTRUE(passed)) "PASS" else "FAIL"

  if (is.finite(sample_mean) && is.finite(sample_sd)) {
    if (is.finite(expected_mean) && is.finite(expected_sd)) {
      stat_msg <- sprintf(
        "mean = %.4f (expected = %.4f), sd = %.4f (expected = %.4f)%s",
        sample_mean, expected_mean, sample_sd, expected_sd,
        if (nzchar(note)) paste0(", ", note) else ""
      )
    } else {
      stat_msg <- sprintf(
        "mean = %.4f, sd = %.4f%s",
        sample_mean, sample_sd,
        if (nzchar(note)) paste0(", ", note) else ""
      )
    }
  } else {
    stat_msg <- sprintf(
      "mean = NA, sd = NA%s",
      if (nzchar(note)) paste0(" [", note, "]") else ""
    )
  }

  cat(sprintf("%s: %s | %s\n", test_name, status_str, stat_msg))

  results_env$rows[[length(results_env$rows) + 1L]] <- data.frame(
    test_name = test_name,
    passed = isTRUE(passed),
    sample_mean = sample_mean,
    expected_mean = expected_mean,
    sample_sd = sample_sd,
    expected_sd = expected_sd,
    note = note,
    stringsAsFactors = FALSE
  )
}

#' Run a formal stochastic goodness-of-fit & moment test on a known distribution
run_distribution_test <- function(results_env,
                                  test_name,
                                  description,
                                  sampler_fn,
                                  true_mean,
                                  true_sd,
                                  cdf_fn = NULL,
                                  z_tol = 4.0,
                                  sd_rel_tol = 0.06,
                                  ks_alpha = 0.005) {
  cat(sprintf("\n[Testing Distribution] %s\n", description))

  draws <- tryCatch(
    sampler_fn(),
    error = function(e) {
      record_test_result(
        results_env, test_name, FALSE,
        expected_mean = true_mean, expected_sd = true_sd,
        note = paste("Unexpected error:", conditionMessage(e))
      )
      return(NULL)
    }
  )
  if (is.null(draws)) {
    return(invisible(NULL))
  }

  n_draws <- length(draws)
  s_mean <- mean(draws)
  s_sd <- stats::sd(draws)

  # Monte Carlo Z-score for sample mean: |X_bar - mu| / (sigma / sqrt(n))
  mean_se <- true_sd / sqrt(n_draws)
  z_score <- abs(s_mean - true_mean) / mean_se
  sd_rel_err <- abs(s_sd - true_sd) / true_sd

  ks_pval <- NA_real_
  ks_ok <- TRUE
  if (!is.null(cdf_fn)) {
    ks_res <- suppressWarnings(stats::ks.test(draws, cdf_fn))
    ks_pval <- ks_res$p.value
    ks_ok <- is.finite(ks_pval) && (ks_pval > ks_alpha)
  }

  passed <- is.finite(s_mean) && is.finite(s_sd) &&
    (z_score < z_tol) && (sd_rel_err < sd_rel_tol) && ks_ok

  note_str <- if (!is.null(cdf_fn)) {
    sprintf("|Z_mean| = %.2f, KS p-value = %.4f", z_score, ks_pval)
  } else {
    sprintf("|Z_mean| = %.2f, rel_sd_err = %.4f", z_score, sd_rel_err)
  }

  record_test_result(
    results_env,
    test_name = test_name,
    passed = passed,
    sample_mean = s_mean,
    expected_mean = true_mean,
    sample_sd = s_sd,
    expected_sd = true_sd,
    note = note_str
  )

  invisible(draws)
}

#' Verify that an invalid or non-log-concave call cleanly raises an error
run_error_expectation_test <- function(results_env, test_name, description, expr_fn) {
  cat(sprintf("\n[Testing Error Handling] %s\n", description))
  caught_msg <- NULL
  errored <- tryCatch(
    {
      expr_fn()
      FALSE
    },
    error = function(e) {
      caught_msg <<- conditionMessage(e)
      TRUE
    }
  )

  note <- if (errored) {
    sprintf("Caught expected error: %s", caught_msg)
  } else {
    "Expected an error, but call succeeded without error"
  }

  record_test_result(results_env, test_name = test_name, passed = errored, note = note)
}

#' Formal Test Suite for Adaptive Rejection Sampler and Internal Modules
#'
#' Executes unit tests on internal modules, stochastic distribution shape/moment
#' tests against analytical truth, runtime non-log-concavity detection tests,
#' and input validation tests. Also writes sample output files to /app.
#'
#' @param n_samples Number of draws per distribution test (default: 10000L).
#' @param seed Integer RNG seed for reproducible stochastic verification (default: 2026L).
#' @param save_samples Logical; if TRUE, writes normal and exponential samples to disk.
#' @param output_dir Directory where sample files are saved (default: "/app").
#' @return Invisibly returns a data.frame summarizing all test outcomes.
test <- function(n_samples = 10000L,
                 seed = 2026L,
                 save_samples = TRUE,
                 output_dir = "/app") {
  set.seed(seed)
  results_env <- new.env(parent = emptyenv())
  results_env$rows <- list()

  cat("==============================================================================\n")
  cat("Adaptive Rejection Sampler (Gilks & Wild, 1992) - Formal Test Suite\n")
  cat(sprintf("Configuration: n_samples = %d, seed = %d\n", n_samples, seed))
  cat("==============================================================================\n")

  # ----------------------------------------------------------------------------
  # Section A: Modular Component Unit Tests
  # ----------------------------------------------------------------------------
  cat("\n--- Section 1: Internal Module Unit Tests ---\n")

  # Module Test 1: Numerical log-density & derivative accuracy (interior + boundary)
  cat("\n[Testing Module] Numerical log-density and derivative accuracy on Gamma(3, 2)...\n")
  mod1_ok <- tryCatch({
    v_mod1 <- validate_ars_inputs(
      f = stats::dgamma, n = 10L, domain = c(0, Inf),
      extra_args = list(shape = 3, rate = 2), eval_env = environment()
    )
    pts <- c(1e-4, 0.25, 1.0, 2.5, 6.0)
    hd <- compute_log_density_and_deriv(v_mod1$target, pts)
    true_h <- stats::dgamma(pts, shape = 3, rate = 2, log = TRUE)
    true_hp <- 2.0 / pts - 2.0
    err_h <- max(abs(hd$h - true_h))
    err_hp <- max(abs(hd$h_prime - true_hp))
    list(ok = (err_h < 1e-12) && (err_hp < 1e-5), vals = hd$h_prime, exp_vals = true_hp, err = err_hp)
  }, error = function(e) list(ok = FALSE, vals = NA_real_, exp_vals = NA_real_, err = Inf))

  record_test_result(
    results_env, "TEST_MODULE_DERIVATIVE", mod1_ok$ok,
    sample_mean = mean(mod1_ok$vals), expected_mean = mean(mod1_ok$exp_vals),
    sample_sd = stats::sd(mod1_ok$vals), expected_sd = stats::sd(mod1_ok$exp_vals),
    note = sprintf("max |h' - true_h'| = %.2e", mod1_ok$err)
  )

  # Module Test 2: Exact hull tangent intersections, log-areas, and envelope bounds
  cat("\n[Testing Module] Piecewise-linear hull intersections, areas, and l(x) <= h(x) <= u(x)...\n")
  x_kn <- c(-2.0, 0.0, 2.0)
  h_kn <- -0.5 * x_kn^2
  hp_kn <- -x_kn
  hull_kn <- construct_hull(x_kn, h_kn, hp_kn, domain = c(-Inf, Inf))
  # Analytical truth for h(x) = -0.5 x^2 at (-2, 0, 2):
  # z = (-Inf, -1, 1, Inf), areas = (0.5, 2.0, 0.5), total = 3.0, probs = (1/6, 4/6, 1/6)
  z_err <- max(abs(hull_kn$z[2:3] - c(-1.0, 1.0)))
  prob_err <- max(abs(hull_kn$probs - c(1 / 6, 4 / 6, 1 / 6)))
  area_err <- abs(exp(hull_kn$log_total_area) - 3.0)
  grid_chk <- seq(-5, 5, length.out = 501L)
  u_chk <- eval_upper_hull(hull_kn, grid_chk)
  l_chk <- eval_lower_hull(hull_kn, grid_chk)
  h_chk <- -0.5 * grid_chk^2
  env_ok <- all(u_chk >= h_chk - 1e-12) && all(l_chk <= h_chk + 1e-12)
  mod2_ok <- (z_err < 1e-12) && (prob_err < 1e-12) && (area_err < 1e-12) && env_ok

  record_test_result(
    results_env, "TEST_MODULE_HULL_GEOMETRY", mod2_ok,
    sample_mean = mean(u_chk), expected_mean = mean(u_chk),
    sample_sd = stats::sd(u_chk), expected_sd = stats::sd(u_chk),
    note = sprintf("z_err = %.2e, prob_err = %.2e, area_err = %.2e", z_err, prob_err, area_err)
  )

  # Module Test 3: Upper-hull piecewise-exponential exact sampler moments
  # For s_3(x) with z = (-Inf, -1, 1, Inf), p = (1/6, 4/6, 1/6), slopes = (2, 0, -2):
  # Exact mean = 0, exact variance = (1/6)*2.5 + (4/6)*(1/3) + (1/6)*2.5 = 19/18
  cat("\n[Testing Module] Sampling directly from piecewise-exponential upper hull s_k(x)...\n")
  hull_draws <- sample_upper_hull(hull_kn, m = 20000L)$x
  true_hull_sd <- sqrt(19.0 / 18.0)
  hull_z <- abs(mean(hull_draws) - 0.0) / (true_hull_sd / sqrt(20000L))
  hull_sd_err <- abs(stats::sd(hull_draws) - true_hull_sd) / true_hull_sd
  mod3_ok <- (hull_z < 4.0) && (hull_sd_err < 0.04)

  record_test_result(
    results_env, "TEST_MODULE_HULL_SAMPLER", mod3_ok,
    sample_mean = mean(hull_draws), expected_mean = 0.0,
    sample_sd = stats::sd(hull_draws), expected_sd = true_hull_sd,
    note = sprintf("|Z_mean| = %.2f, rel_sd_err = %.4f", hull_z, hull_sd_err)
  )

  # Module Test 4: Adaptive hull insertion tightens upper envelope integral monotonically
  cat("\n[Testing Module] Adaptive abscissa insertion and envelope tightening...\n")
  hull_upd <- insert_abscissa(hull_kn, x_new = 1.0, h_new = -0.5, h_prime_new = -1.0)
  mod4_ok <- (hull_upd$k == 4L) &&
    isTRUE(all.equal(hull_upd$x, c(-2.0, 0.0, 1.0, 2.0))) &&
    (hull_upd$log_total_area < hull_kn$log_total_area)

  record_test_result(
    results_env, "TEST_MODULE_HULL_UPDATE", mod4_ok,
    sample_mean = mean(hull_upd$x), expected_mean = 0.25,
    sample_sd = stats::sd(hull_upd$x), expected_sd = stats::sd(c(-2.0, 0.0, 1.0, 2.0)),
    note = sprintf("area tightened from %.4f to %.4f", exp(hull_kn$log_total_area), exp(hull_upd$log_total_area))
  )

  # Module Test 5: Automatic abscissa & support initialization without user hints
  cat("\n[Testing Module] Automatic initialization on shifted Normal N(45, 0.5^2) and Beta(2, 5)...\n")
  v_shift <- validate_ars_inputs(
    stats::dnorm, n = 10L, domain = c(-Inf, Inf),
    extra_args = list(mean = 45, sd = 0.5), eval_env = environment()
  )
  init_shift <- initialize_abscissae(v_shift$target)
  v_beta <- validate_ars_inputs(
    stats::dbeta, n = 10L, domain = c(-Inf, Inf),
    extra_args = list(shape1 = 2, shape2 = 5), eval_env = environment()
  )
  init_beta <- initialize_abscissae(v_beta$target)
  mod5_ok <- (init_shift$h_prime[1L] > 0) &&
    (init_shift$h_prime[length(init_shift$h_prime)] < 0) &&
    (abs(init_beta$target$domain[1L] - 0.0) < 1e-6) &&
    (abs(init_beta$target$domain[2L] - 1.0) < 1e-6)

  record_test_result(
    results_env, "TEST_MODULE_INITIALIZATION", mod5_ok,
    sample_mean = mean(init_shift$x), expected_mean = 45.0,
    sample_sd = stats::sd(init_shift$x), expected_sd = stats::sd(init_shift$x),
    note = sprintf("detected Beta support = [%.6f, %.6f]", init_beta$target$domain[1L], init_beta$target$domain[2L])
  )

  # ----------------------------------------------------------------------------
  # Section B: Known Log-Concave Distributions (End-to-End Stochastic Tests)
  # ----------------------------------------------------------------------------
  cat("\n--- Section 2: Known Log-Concave Distribution Tests ---\n")

  norm_draws <- run_distribution_test(
    results_env,
    test_name = "TEST_STANDARD_NORMAL",
    description = "Standard Normal N(0, 1) via ars(dnorm, n)",
    sampler_fn = function() ars(stats::dnorm, n = n_samples),
    true_mean = 0.0,
    true_sd = 1.0,
    cdf_fn = stats::pnorm
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_SHIFTED_NORMAL",
    description = "Shifted & Scaled Normal N(mean = 12, sd = 2.5) via extra '...' parameters",
    sampler_fn = function() ars(stats::dnorm, n = n_samples, mean = 12, sd = 2.5),
    true_mean = 12.0,
    true_sd = 2.5,
    cdf_fn = function(q) stats::pnorm(q, mean = 12, sd = 2.5)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_TRUNCATED_HALF_NORMAL",
    description = "Half-Normal (Standard Normal truncated to [0, Inf))",
    sampler_fn = function() ars(stats::dnorm, n = n_samples, domain = c(0, Inf)),
    true_mean = sqrt(2.0 / pi),
    true_sd = sqrt(1.0 - 2.0 / pi),
    cdf_fn = function(q) ifelse(q < 0, 0, 2.0 * stats::pnorm(q) - 1.0)
  )

  exp_draws <- run_distribution_test(
    results_env,
    test_name = "TEST_STANDARD_EXPONENTIAL",
    description = "Standard Exponential Exp(rate = 1) on [0, Inf)",
    sampler_fn = function() ars(stats::dexp, n = n_samples, domain = c(0, Inf)),
    true_mean = 1.0,
    true_sd = 1.0,
    cdf_fn = stats::pexp
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_EXPONENTIAL_AUTO_DOMAIN",
    description = "Exponential Exp(rate = 2.5) without explicit domain (automatic support detection)",
    sampler_fn = function() ars(stats::dexp, n = n_samples, rate = 2.5),
    true_mean = 0.4,
    true_sd = 0.4,
    cdf_fn = function(q) stats::pexp(q, rate = 2.5)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_GAMMA_DISTRIBUTION",
    description = "Gamma(shape = 3, rate = 2) on [0, Inf)",
    sampler_fn = function() ars(stats::dgamma, n = n_samples, domain = c(0, Inf), shape = 3, rate = 2),
    true_mean = 1.5,
    true_sd = sqrt(3.0) / 2.0,
    cdf_fn = function(q) stats::pgamma(q, shape = 3, rate = 2)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_BETA_DISTRIBUTION",
    description = "Beta(shape1 = 2, shape2 = 5) on compact support [0, 1]",
    sampler_fn = function() ars(stats::dbeta, n = n_samples, domain = c(0, 1), shape1 = 2, shape2 = 5),
    true_mean = 2.0 / 7.0,
    true_sd = sqrt((2.0 * 5.0) / (49.0 * 8.0)),
    cdf_fn = function(q) stats::pbeta(q, shape1 = 2, shape2 = 5)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_UNIFORM_DISTRIBUTION",
    description = "Uniform(-2, 4) log-flat density on [-2, 4]",
    sampler_fn = function() ars(stats::dunif, n = n_samples, domain = c(-2, 4), min = -2, max = 4),
    true_mean = 1.0,
    true_sd = 6.0 / sqrt(12.0),
    cdf_fn = function(q) stats::punif(q, min = -2, max = 4)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_LOGISTIC_DISTRIBUTION",
    description = "Standard Logistic(0, 1) distribution",
    sampler_fn = function() ars(stats::dlogis, n = n_samples),
    true_mean = 0.0,
    true_sd = pi / sqrt(3.0),
    cdf_fn = stats::plogis
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_UNNORMALIZED_DENSITY",
    description = "Unnormalized Laplace density f(x) = 37.5 * exp(-|x - 2|) with arbitrary scale",
    sampler_fn = function() ars(function(x) 37.5 * exp(-abs(x - 2.0)), n = n_samples),
    true_mean = 2.0,
    true_sd = sqrt(2.0),
    cdf_fn = function(q) ifelse(q < 2.0, 0.5 * exp(q - 2.0), 1.0 - 0.5 * exp(-(q - 2.0)))
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_EXPRESSION_INPUT",
    description = "R expression input expression(exp(-0.5 * (x - 3)^2)) for unnormalized N(3, 1)",
    sampler_fn = function() ars(expression(exp(-0.5 * (x - 3)^2)), n = n_samples),
    true_mean = 3.0,
    true_sd = 1.0,
    cdf_fn = function(q) stats::pnorm(q, mean = 3.0, sd = 1.0)
  )

  run_distribution_test(
    results_env,
    test_name = "TEST_EXTREME_UNNORMALIZED_SCALE",
    description = "Extreme small scale f(x) = 1e-150 * exp(-0.5 * x^2) testing log-space stability",
    sampler_fn = function() ars(function(x) 1e-150 * exp(-0.5 * x^2), n = n_samples),
    true_mean = 0.0,
    true_sd = 1.0,
    cdf_fn = stats::pnorm
  )

  # ----------------------------------------------------------------------------
  # Section C: Non-Log-Concave Density Detection (Initialization & Runtime)
  # ----------------------------------------------------------------------------
  cat("\n--- Section 3: Non-Log-Concave Density Detection Tests ---\n")

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_CAUCHY_RUNTIME",
    description = "Cauchy initialized on locally log-concave core [-0.4, 0, 0.4] (must catch during sampling)",
    expr_fn = function() ars(stats::dcauchy, n = 500L, x_init = c(-0.4, -0.2, 0.0, 0.2, 0.4))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_STUDENT_T_RUNTIME",
    description = "Student-t(df = 2) initialized inside locally concave core [-0.5, 0.5] (caught during sampling)",
    expr_fn = function() ars(stats::dt, n = 500L, df = 2, x_init = c(-0.5, -0.25, 0.0, 0.25, 0.5))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_BIMODAL_MIXTURE",
    description = "Bimodal Gaussian mixture 0.5*N(-3, 1) + 0.5*N(3, 1)",
    expr_fn = function() ars(function(x) 0.5 * stats::dnorm(x, -3, 1) + 0.5 * stats::dnorm(x, 3, 1), n = 500L)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_GAMMA_SUBUNITY",
    description = "Gamma(shape = 0.5, rate = 1) which is strictly log-convex on (0, Inf)",
    expr_fn = function() ars(stats::dgamma, n = 200L, domain = c(0, Inf), shape = 0.5, rate = 1)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_BETA_USHAPED",
    description = "U-shaped Beta(0.5, 0.5) which is log-convex on (0, 1)",
    expr_fn = function() ars(stats::dbeta, n = 200L, domain = c(0, 1), shape1 = 0.5, shape2 = 0.5)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_NON_LOGCONCAVE_LOGNORMAL",
    description = "Log-normal distribution dlnorm (heavy non-log-concave right tail)",
    expr_fn = function() ars(stats::dlnorm, n = 500L, domain = c(0, Inf))
  )

  # ----------------------------------------------------------------------------
  # Section D: Input Validation Error Handling Tests
  # ----------------------------------------------------------------------------
  cat("\n--- Section 4: Input Validation & Error Handling Tests ---\n")

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_NEGATIVE_N",
    description = "Reject negative sample count n = -10",
    expr_fn = function() ars(stats::dnorm, n = -10)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_ZERO_OR_NONINT_N",
    description = "Reject non-integer sample count n = 3.5",
    expr_fn = function() ars(stats::dnorm, n = 3.5)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_DOMAIN_ORDER",
    description = "Reject inverted domain c(5, -2) where lower >= upper",
    expr_fn = function() ars(stats::dnorm, n = 100, domain = c(5, -2))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_ZERO_DENSITY_DOMAIN",
    description = "Reject domain c(-10, -1) where Exponential density is identically zero",
    expr_fn = function() ars(stats::dexp, n = 100, domain = c(-10, -1))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_NONVECTORIZED_FN",
    description = "Reject non-vectorized function returning scalar of wrong length",
    expr_fn = function() ars(function(x) 1.0, n = 100, domain = c(0, 1))
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_NEGATIVE_DENSITY",
    description = "Reject function that evaluates to negative values",
    expr_fn = function() ars(function(x) -stats::dnorm(x), n = 100)
  )

  run_error_expectation_test(
    results_env,
    test_name = "TEST_INVALID_XINIT_OUT_OF_DOMAIN",
    description = "Reject x_init containing points outside specified domain",
    expr_fn = function() ars(stats::dnorm, n = 100, domain = c(0, Inf), x_init = c(-1, 1, 2))
  )

  # ----------------------------------------------------------------------------
  # Save generated samples to /app/normal_samples.txt & /app/exponential_samples.txt
  # ----------------------------------------------------------------------------
  if (isTRUE(save_samples) && dir.exists(output_dir)) {
    if (!is.null(norm_draws)) {
      norm_path <- file.path(output_dir, "normal_samples.txt")
      write(norm_draws, file = norm_path, ncolumns = 1L)
      cat(sprintf("\nSaved %d standard normal ARS samples to %s\n", length(norm_draws), norm_path))
    }
    if (!is.null(exp_draws)) {
      exp_path <- file.path(output_dir, "exponential_samples.txt")
      write(exp_draws, file = exp_path, ncolumns = 1L)
      cat(sprintf("Saved %d standard exponential ARS samples to %s\n", length(exp_draws), exp_path))
    }
  }

  summary_df <- do.call(rbind, results_env$rows)
  n_total <- nrow(summary_df)
  n_pass <- sum(summary_df$passed)

  cat("\n==============================================================================\n")
  if (n_pass == n_total) {
    cat(sprintf("OVERALL RESULT: ALL %d TESTS PASSED (%d/%d)\n", n_total, n_pass, n_total))
  } else {
    cat(sprintf("OVERALL RESULT: %d/%d TESTS PASSED (%d UNEXPECTED OUTCOMES)\n", n_pass, n_total, n_total - n_pass))
  }
  cat("==============================================================================\n")

  invisible(summary_df)
}

